1	package com.example.starter.damage.service;
2	
3	import com.example.starter.damage.dto.Requests.ApprovalRequest;
4	import com.example.starter.damage.dto.Requests.CloseRequest;
5	import com.example.starter.damage.dto.Requests.CompletionRequest;
6	import com.example.starter.damage.dto.Requests.EstimateRequest;
7	import com.example.starter.damage.dto.Requests.PhotoRequest;
8	import com.example.starter.damage.dto.Requests.RegisterRequest;
9	import com.example.starter.damage.dto.Requests.ReinspectionRequest;
10	import com.example.starter.damage.dto.Requests.SurveyRequest;
11	import com.example.starter.damage.dto.Views.ApprovalView;
12	import com.example.starter.damage.dto.Views.CaseDetailView;
13	import com.example.starter.damage.dto.Views.CaseView;
14	import com.example.starter.damage.dto.Views.CompletionView;
15	import com.example.starter.damage.dto.Views.EstimateView;
16	import com.example.starter.damage.dto.Views.PhotoResult;
17	import org.springframework.stereotype.Service;
18	
19	/**
20	 * 残损案门面服务：检验、估价与放行等写操作均以 requestId 幂等，
21	 * 指纹覆盖 requestId 与全部业务字段，同键同参返回首次结果，同键异参返回 409。
22	 */
23	@Service
24	public class DamageCaseService {
25	
26	    private final DamageCaseTxService txService;
27	    private final IdempotencyExecutor idempotency;
28	
29	    public DamageCaseService(DamageCaseTxService txService, IdempotencyExecutor idempotency) {
30	        this.txService = txService;
31	        this.idempotency = idempotency;
32	    }
33	
34	    /** 到港登记（幂等） */
35	    public CaseView register(RegisterRequest request) {
36	        return idempotency.execute("REGISTER", request.requestId(), request, CaseView.class,
37	                () -> txService.register(request));
38	    }
39	
40	    /** 检验登记（幂等） */
41	    public CaseDetailView survey(long caseId, SurveyRequest request) {
42	        return idempotency.execute("SURVEY#" + caseId, request.requestId(), request, CaseDetailView.class,
43	                () -> txService.survey(caseId, request));
44	    }
45	
46	    /** 估价（幂等；同键异参 409 且不产生新估价版本） */
47	    public EstimateView estimate(long caseId, EstimateRequest request) {
48	        return idempotency.execute("ESTIMATE#" + caseId, request.requestId(), request, EstimateView.class,
49	                () -> txService.estimate(caseId, request));
50	    }
51	
52	    /** 修理批复（幂等） */
53	    public ApprovalView approve(long caseId, ApprovalRequest request) {
54	        return idempotency.execute("APPROVE#" + caseId, request.requestId(), request, ApprovalView.class,
55	                () -> txService.approve(caseId, request));
56	    }
57	
58	    /** 修理完工（幂等） */
59	    public CompletionView completeRepair(long caseId, CompletionRequest request) {
60	        return idempotency.execute("COMPLETE#" + caseId, request.requestId(), request, CompletionView.class,
61	                () -> txService.completeRepair(caseId, request));
62	    }
63	
64	    /** 复检（幂等） */
65	    public CaseView reinspect(long caseId, ReinspectionRequest request) {
66	        return idempotency.execute("REINSPECT#" + caseId, request.requestId(), request, CaseView.class,
67	                () -> txService.reinspect(caseId, request));
68	    }
69	
70	    /** 结案放行（幂等；重复结案返回幂等成功） */
71	    public CaseView close(long caseId, CloseRequest request) {
72	        return idempotency.execute("CLOSE#" + caseId, request.requestId(), request, CaseView.class,
73	                () -> txService.close(caseId, request));
74	    }
75	
76	    /** 检验照片登记；结案后迟到照片只记迟到事件 */
77	    public PhotoResult photo(long caseId, PhotoRequest request) {
78	        return txService.photo(caseId, request);
79	    }
80	
81	    /** 案件全量明细 */
82	    public CaseDetailView detail(long caseId) {
83	        return txService.detail(caseId);
84	    }
85	}
86

