        return service.photo(caseId, request);
    }

    /** 案件全量明细：残损清单、估价版本与修理链 */
    @GetMapping("/{caseId}")
    public CaseDetailView detail(@PathVariable long caseId) {
        return service.detail(caseId);
    }
}

