23	import java.util.UUID;
24	import java.util.concurrent.CountDownLatch;
25	import java.util.concurrent.ExecutorService;
26	import java.util.concurrent.Executors;
27	import java.util.concurrent.Future;
28	import java.util.concurrent.TimeUnit;
29	
30	import static org.assertj.core.api.Assertions.assertThat;
31	
32	/**
33	 * 并发测试：真实 H2 约束与事务边界下，协调多线程同时提交，
34	 * 验证同一箱号并发登记唯一受理、同 requestId 并发重放不产生新估价版本。
35	 */
36	@SpringBootTest
37	class DamageConcurrencyTest {
38	
39	    private static final int THREADS = 8;
40	
41	    @Autowired
42	    private DamageCaseService service;
43	
44	    @Autowired
45	    private JdbcTemplate jdbc;
46	
47	    private ExecutorService pool;
48	
49	    @BeforeEach
50	    void setUp() {
51	        jdbc.update("delete from case_event");
52	        jdbc.update("delete from reinspection");
53	        jdbc.update("delete from repair_completion");
54	        jdbc.update("delete from repair_approval");
55	        jdbc.update("delete from estimate");
56	        jdbc.update("delete from damage_item");
57	        jdbc.update("delete from damage_case");
58	        jdbc.update("delete from idempotency_record");
59	        pool = Executors.newFixedThreadPool(THREADS);
60	    }
61	
62	    @AfterEach
63	    void tearDown() {
64	        pool.shutdownNow();
65	    }
66	
67	    private <T> List<T> runConcurrently(java.util.concurrent.Callable<T> task) throws Exception {
68	        CountDownLatch ready = new CountDownLatch(THREADS);
69	        CountDownLatch start = new CountDownLatch(1);
70	        List<Future<T>> futures = new ArrayList<>();
71	        for (int i = 0; i < THREADS; i++) {
72	            futures.add(pool.submit(() -> {
73	                ready.countDown();
74	                assertThat(start.await(5, TimeUnit.SECONDS)).isTrue();
75	                return task.call();
76	            }));
77	        }
78	        assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
79	        start.countDown();
80	        List<T> results = new ArrayList<>();
81	        for (Future<T> future : futures) {
82	            results.add(future.get(30, TimeUnit.SECONDS));
83	        }
84	        return results;
85	    }
86	
87	    @Test
88	    void concurrentRegisterSameContainer_onlyOneAccepted() throws Exception {
89	        List<Object> results = runConcurrently(() -> {
90	            String requestId = "reg-conc-" + UUID.randomUUID();
91	            try {
92	                return service.register(new RegisterRequest(requestId, "CSQU3054383", new BigDecimal("10000.00")));
93	            } catch (ApiException e) {
94	                return e;
95	            }
96	        });
97	
98	        long succeeded = results.stream().filter(CaseView.class::isInstance).count();
99	        long conflicted = results.stream()
100	                .filter(ApiException.class::isInstance)
101	                .map(ApiException.class::cast)
102	                .filter(e -> e.status() == HttpStatus.CONFLICT)
103	                .count();
104	        assertThat(succeeded).isEqualTo(1);
105	        assertThat(conflicted).isEqualTo(THREADS - 1);
106	
107	        Integer activeCases = jdbc.queryForObject(
108	                "select count(*) from damage_case where active_key is not null", Integer.class);
109	        assertThat(activeCases).isEqualTo(1);
110	        Integer totalCases = jdbc.queryForObject("select count(*) from damage_case", Integer.class);
111	        assertThat(totalCases).isEqualTo(1);
112	    }
113	
114	    @Test
115	    void concurrentSameEstimateRequest_singleVersionAndSameResult() throws Exception {
116	        CaseView registered = service.register(new RegisterRequest(
117	                "reg-" + UUID.randomUUID(), "TEMU2000001", new BigDecimal("10000.00")));
118	        long caseId = registered.id();
