comment on table bid_item is '报价逐项明细；整版覆盖全部询价项，金额为正整数分，工法须在允许集合且供应商适用';
comment on column bid_item.amount_cents is '该项报价，正整数分，必须大于 0';

create table if not exists bid_opening (
