    public Optional<InquiryRow> findOpenByCase(long caseId) {
        return jdbc.query("select * from inquiry where case_id = ? and status = 'OPEN' order by version desc",
                        INQUIRY_MAPPER, caseId)
                .stream().findFirst();
    }

