            String description,
            @NotNull Responsibility responsibility,
            @NotNull @DecimalMin(value = "0.00", message = "修理费不得为负") BigDecimal repairCost) {
    }

    /** 检验登记请求 */
    public record SurveyRequest(
            @NotBlank String requestId,
            @NotEmpty List<@Valid DamageItemInput> items) {
    }

