     * 成功后供应商版本与资格版本号同时加 1。
     */
    public record QualificationRenewRequest(
            @NotBlank String requestId,
            @Positive int expectedVersion,
            @NotNull LocalDateTime validFrom,
            @NotNull LocalDateTime validTo) {
    }

