 * 业务代码仍按 Clock 类型注入，测试可显式拨针验证截止时刻边界。
 */
@TestConfiguration
public class TestClockConfig {

    @Bean
    @Primary
    public MutableUtcClock businessClock() {
        return MutableUtcClock.startAt(LocalDateTime.of(2026, 10, 1, 0, 0, 0));
    }
}

