    private long registeredCase(String body, String requestIdPrefix) throws Exception {
        String json = mvc.perform(post("/api/cases")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return Long.parseLong(json.replaceAll(".*\"id\":(\\d+).*", "$1"));
    }

    private long repairCase(String no) throws Exception {
        long caseId = registeredCase(
                "{\"requestId\":\"reg-" + no + "\",\"containerNo\":\"" + no + "\",\"containerValue\":10000.00}", "reg");
