                                  {"damageItemId":%d,"allowedMethods":["WELD"]},
                                  {"damageItemId":%d,"allowedMethods":["PATCH"]}]}
                                """.formatted(item1, item2)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.version", is(1)))
                .andExpect(jsonPath("$.status", is("OPEN")))
