        long inquiryId = Long.parseLong(inquiryJson.replaceAll(".*\"id\":(\\d+).*", "$1"));
        long inqItem1 = Long.parseLong(inquiryJson.replaceAll(
                ".*\"items\":\\[\\{\"id\":(\\d+).*", "$1"));
