                .andExpect(jsonPath("$.revision", is(1)))
                .andExpect(jsonPath("$.totalAmountCents", is(3000)));
        mvc.perform(post("/api/inquiries/{id}/bids", inquiryId)
                        .contentType(MediaType.APPLICATION_JSON).content("""
                                {"requestId":"bid-b","supplierCode":"SUP-B","expectedVersion":0,"items":[
                                  {"inquiryItemId":%d,"methodCode":"WELD","amountCents":1500},
                                  {"inquiryItemId":%d,"methodCode":"PATCH","amountCents":1400}]}
                                """.formatted(inqItem1, inqItem2)))
                .andExpect(status().isOk());

