@SpringBootTest
@AutoConfigureMockMvc
@Import(TestClockConfig.class)
class SealedInquiryApiTest {

    private static final LocalDateTime DEADLINE = LocalDateTime.of(2026, 10, 1, 12, 0, 0);

    @Autowired
    private MockMvc mvc;
