    List<Frozen> ranked = frozen.stream()
            .filter(Frozen::qualified)
            .sorted(Comparator.comparingLong((Frozen f) -> f.bid().totalAmountCents())
                    .thenComparing(f -> f.supplier().code()))
            .toList();
    Frozen winner = ranked.isEmpty() ? null : ranked.get(0);

